  ('TSE-0050', 'Permanent Housing program- Community Restoration Project', NULL, 'Cobb Resources.xlsx', NULL, NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.communityrestorationproject.org/', 'Shelter & Housing', NULL, 'Individuals enrolled in the Permanent Housing program have their immediate housing needs met, which includes a room in a shared living space along with bedroom and living room furniture. Over the course of the program, individuals share living spaces with a roommate of the same sex. We provide housing through a CRP sublease; rent is divided equally and households received a monthly credit for electricity', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', 'No', NULL, 'Unverified', NULL, 'EIN not found in ProPublica', NULL, 'unclaimed', FALSE),
  ('TSE-0051', 'Motel to Home- Community Restoration Project', NULL, 'Cobb Resources.xlsx', NULL, NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '(Laura) 404.454.9990/ (Erika) 404.587.5488', NULL, '(Laura) lloughin@communityrestorationproject.org/ (Erika) ehowrad@communityrestorationproject.org', 'https://www.communityrestorationproject.org/', 'Shelter & Housing', NULL, 'CRP provides each family up to $4,000 for their security deposit and first month''s rent.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', 'No', NULL, 'Unverified', NULL, 'to qualify they must have consistent income, at least 1 school-aged child, and have resided in a motel/extended stay for +30 days. | EIN not found in ProPublica', NULL, 'unclaimed', FALSE),
