  ('TSE-0057', 'Home Stretch', NULL, 'Cobb Resources.xlsx', '89 Grove Way Roswell GA 30075', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '770-642-9185 x112', NULL, NULL, 'https://homestretch.org/get-help/', 'Shelter & Housing', NULL, 'HomeStretch offers working homeless families a proven path toward financial stability, improved employment, stronger family relationships and permanent affordable housing. The HomeStretch Supportive Housing program has 23 two- and three-bedroom apartments.  Four are ADA accessible.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', 'No', NULL, 'Unverified', NULL, 'To be eligible for the HomeStretch Supportive Housing programs, you must: Be homeless or imminently homeless. Be employed full-time - documented with pay stubs showing at least 37.5 hours worked per week. Have custody of minor child(children) in residence. Have a connection to the greater north metro Atlanta area such as employment or school. | EIN not found in ProPublica', NULL, 'unclaimed', FALSE),
  ('TSE-0058', 'Kids Home Initiative- Community Restoration Project', NULL, 'Cobb Resources.xlsx', NULL, NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '(Victoria) 404.604.4548', NULL, '(Victoria) vpinell@communityrestorationproject.org', 'https://www.communityrestorationproject.org/', 'Shelter & Housing', NULL, 'Kids Home Initiative is a resource for homeless and housing-instable families. CRP provides a well-rounded, individualized solution to house each family. Solutions include up to $4,000 for remedying housing barriers as well as food assistance.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', 'No', NULL, 'Unverified', NULL, 'Must be referred by a school counselor. | EIN not found in ProPublica', NULL, 'unclaimed', FALSE),
