  ('TSE-0077', 'Safe Families for Children', NULL, 'Cobb Resources.xlsx', 'PO Box 1985, Woodstock GA 30188', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '770-328-2975', NULL, 'northmetroatl@safefamilies.net', 'https://safe-families.org/about/', 'General Social Services', NULL, 'Provides temporary placement of children into safe vetted homes in situations where care needs to be given to avoid children needing to go into the foster care system.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', 'No', NULL, 'Unverified', NULL, 'The three objectives of Safe Families for Children are:
 
