  ('TSE-0161', 'Foster Cares', NULL, 'Cobb Resources.xlsx', NULL, NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '770-641-9591', NULL, 'info@fostercares.org', 'https://www.fostercares.org/what-we-do', 'Child & Family Services', NULL, 'FosterCares™️ serves a vital and growing need throughout Georgia by providing free clothing, infant equipment and developmental toys to thousands of children in foster and relative care.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', 'No', NULL, 'Unverified', NULL, 'ProPublica match: Linda Foster Cares Inc (EIN 39-2814952, score 0.67)', '39-2814952', 'unclaimed', FALSE),
  ('TSE-0162', 'Bloom', NULL, 'Cobb Resources.xlsx', '115 Marquis Dr. Fayetteville, GA 30214', NULL, 'GA', NULL, 'Cobb', NULL, 'Atlanta Regional CoC (ARC)', 'Atlanta Continuum of Care (GA-500)', NULL, NULL, NULL, '770-461-7020', NULL, 'info@bloomouryouth.org', 'https://bloomouryouth.org/the-bloom-closet/', 'Child & Family Services', NULL, 'The Bloom Closet and The Bloom Closet Express exist for the benefit of displaced children in Georgia. Any child in the following situations can access the free clothing, supplies, and other essentials.  Any Georgia foster child living in the custody of DFCS, including children living in DFCS-approved kinship homes.
College-age foster children attending school who have signed themselves back into DFCS custody. Foster children in an Independent Living Program who have signed themselves back into DFCS custody.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-18', NULL, 'Needs Verification', NULL, NULL, NULL, NULL, 'Prospect', NULL, 'Medium', 'No', NULL, 'Unverified', NULL, 'We require only to see a DFCS placement letter or a referral letter from your caseworker showing that the child you are shopping for is in your care. If you live over an hour away from Fayetteville, GA you can call (770) 461-7020 to request a visit from The Bloom Closet Express. The Express brings the resources of The Bloom Closet directly to underserved communities throughout Georgia. | EIN not found in ProPublica', NULL, 'unclaimed', FALSE),
